<template><SuperAdminLayout><header><div><p>6. CUSTOMERS CENTRE</p><h1>6.1 Customer Profile</h1></div><div><RouterLink to="/super-admin/customers">← Customers List</RouterLink><button @click="toggle">{{customer?.status==='Active'?'Set inactive':'Set active'}}</button></div></header><template v-if="customer"><section class="hero card"><div class="avatar">{{customer.company_name?.slice(0,1)}}</div><div class="facts"><b>ID no.</b><strong>{{customer.customer_number}}</strong><b>Name</b><strong>{{customer.company_name}}</strong><b>Sign up date</b><strong>{{date(customer.sign_up_date)}}</strong><b>Years in service</b><strong>{{years}}</strong></div><div class="facts"><b>Status</b><strong><i :class="customer.status.toLowerCase()">{{customer.status}}</i></strong><b>Current plan</b><strong>{{customer.plan}}</strong><b>Billing cycle</b><strong>{{customer.billing_cycle}}</strong><b>Payment issues</b><strong>{{customer.summary.failed_invoices}}</strong></div><div class="facts"><b>Qty users / licences</b><strong>{{customer.summary.user_licenses}}</strong><b>Paid invoices</b><strong>{{customer.summary.paid_invoices}}</strong><b>Paid amount</b><strong>{{money(customer.summary.paid_amount)}}</strong><b>Account statement</b><strong>Available from Billing</strong></div></section><div class="grid"><Info title="Location" :items="[['Country',customer.country],['State / Province',customer.state],['City',customer.city],['ZIP / Postal Code',customer.postal_code]]"/><Info title="Director" :items="[['Name',customer.director.name],['Phone',customer.director.phone],['Email',customer.director.email]]"/><Info title="Accounting" :items="[['Name',customer.accounting.name],['Phone',customer.accounting.phone],['Email',customer.accounting.email]]"/><Info title="Admin" :items="[['Name',customer.admin.name],['Phone',customer.admin.phone],['Email',customer.admin.email]]"/></div><section class="card"><h2>Plan &amp; Licence Summary</h2><div class="four"><div><b>Current plan</b><strong>{{customer.plan}}</strong><b>Billing cycle</b><strong>{{customer.billing_cycle}}</strong></div><div><b>Monthly Payment History</b><table><tbody><tr v-for="x in customer.payment_history" :key="x.invoice_number"><td>{{date(x.date)}}</td><td>{{money(x.amount_paid,x.currency)}}</td><td>{{x.status}}</td></tr></tbody></table></div><div><b>Payment Methods</b><table><tbody><tr v-for="x in customer.payment_methods" :key="x.details"><td>{{x.method}}</td><td>{{x.details}}</td><td>{{x.status}}</td></tr><tr v-if="!customer.payment_methods.length"><td>No payment method recorded.</td></tr></tbody></table></div><div><b>Payment / NSF Records</b><table><tbody><tr v-for="x in customer.nsf_records" :key="x.date"><td>{{date(x.date)}}</td><td>{{money(x.amount)}}</td><td>{{x.reason}}</td></tr><tr v-if="!customer.nsf_records.length"><td>No NSF records.</td></tr></tbody></table></div></div></section><div class="bottom"><section class="card status"><h2>Status</h2><label v-for="s in ['Active','Inactive']" :key="s"><input type="radio" :checked="customer.status===s" @change="setStatus(s)"> {{s}}</label></section><Info title="Account Summary" :items="[['Qty Users / Licences',customer.summary.user_licenses],['Paid invoices',customer.summary.paid_invoices],['Payment issues',customer.summary.failed_invoices],['Paid amount',money(customer.summary.paid_amount)],['Comment','Customer account on the platform']]"/><section class="card"><h2>Status History</h2><table><thead><tr><th>Status</th><th>From date</th><th>To date</th><th>Reason</th></tr></thead><tbody><tr v-for="s in customer.status_history" :key="s.from_date"><td>{{s.status}}</td><td>{{date(s.from_date)}}</td><td>{{date(s.to_date)}}</td><td>{{s.reason}}</td></tr></tbody></table></section></div></template></SuperAdminLayout></template>
<script setup>import{defineComponent,h,onMounted,ref}from'vue';import{RouterLink,useRoute}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const route=useRoute(),customer=ref(null);const date=v=>v?new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric'}).format(new Date(v+'T00:00:00')):'—',money=(v,c='CAD')=>Number(v||0).toLocaleString('en-CA',{style:'currency',currency:c}),years=ref('—');const Info=defineComponent({props:{title:String,items:Array},setup:p=>()=>h('section',{class:'card'},[h('h2',p.title),...p.items.map(x=>h('p',[h('b',x[0]+': '),x[1]||'—']))])});async function load(){const d=(await client.get('/super-admin/customers/'+route.params.id)).data.data;customer.value=d;years.value=d.sign_up_date?Math.max(0,new Date().getFullYear()-new Date(d.sign_up_date).getFullYear())+' years':'—'}async function setStatus(s){await client.patch('/super-admin/customers/'+route.params.id+'/status',{status:s.toLowerCase()});load()}function toggle(){setStatus(customer.value.status==='Active'?'Inactive':'Active')}onMounted(load)</script>
<style scoped>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}header p{margin:0;color:#1761c7;font-size:.72rem;font-weight:800}h1{margin:4px 0;font-size:2rem}a,button{color:#0755dc;font-weight:700;text-decoration:none}button{margin-left:12px;border:0;border-radius:5px;background:#0755dc;color:white;padding:10px 14px}.card{background:#fff;border:1px solid #e0e7f0;border-radius:8px;padding:15px}.hero{display:grid;grid-template-columns:130px repeat(3,1fr);gap:22px}.avatar{height:100px;width:100px;display:grid;place-items:center;border-radius:50%;background:#dbe9fb;color:#3976bc;font-size:2.4rem}.facts{display:grid;grid-template-columns:1.3fr 1fr;gap:11px;font-size:.84rem}.facts b{color:#30415e}.facts i{font-style:normal;padding:4px 8px;border-radius:4px}.active{background:#dcfce7;color:#087a37}.inactive{background:#fee2e2;color:#c22}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:12px 0}.card h2{font-size:1rem;color:#0648ae;margin:0 0 12px}.card p{font-size:.84rem}.four{display:grid;grid-template-columns:1fr 1.3fr 1.4fr 1.3fr;gap:16px}.four div{border-right:1px solid #e4eaf2;padding-right:12px;display:grid;gap:9px;font-size:.8rem}.four strong{font-size:.9rem}table{width:100%;border-collapse:collapse;font-size:.76rem}td,th{padding:7px;border:1px solid #e2e9f2;text-align:left}.bottom{display:grid;grid-template-columns:.75fr 1.6fr 2fr;gap:12px;margin-top:12px}.status label{display:block;padding:9px;border-bottom:1px solid #e7edf5}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,1fr)}.hero{grid-template-columns:100px 1fr 1fr}.facts:last-child{grid-column:2/4}.four,.bottom{grid-template-columns:1fr 1fr}}@media(max-width:600px){header{display:block}.hero,.grid,.four,.bottom{grid-template-columns:1fr}.facts:last-child{grid-column:auto}}</style>
